// Récupère la dernière ligne déjà traitée (idempotence)
const lastLine = Number($node['Get Last Processed Line'].json.last_line || 0);

const lines = (items[0].json.content || '').split('\n');
const out = [];

for (let i = lastLine; i < lines.length; i++) {
  const trimmed = lines[i].trim();
  if (!trimmed) continue;
  try {
    const obj = JSON.parse(trimmed);
    obj._line_number = i + 1;
    out.push({ json: obj });
  } catch (e) {
    // ignore ligne JSON invalide
  }
}

// Expose le nouveau curseur en metadata
if (out.length > 0) {
  out[out.length - 1].json._new_last_line = lines.length;
}

return out;

// Unités standardisées par polluant (3.3 – uniformisation)
const UNIT_MAP = {
  pm25: 'µg/m³',
  pm10: 'µg/m³',
  no2:  'µg/m³',
  o3:   'µg/m³',
  co:   'mg/m³',
  so2:  'µg/m³',
};

const cleaned = [];

for (const item of items) {
  const row = item.json;
  const v = Number(row.value);

  if (Number.isNaN(v) || v < 0 || v > 500) continue;

  const dt = new Date(row.datetime_utc);
  if (isNaN(dt.getTime())) continue;

  const pollutant = (row.pollutant || 'unknown').toLowerCase();
  const unit = UNIT_MAP[pollutant] || row.unit || 'unknown';

  cleaned.push({
    json: {
      sensor_id:    row.sensor_id,
      location_id:  row.location_id || null,
      sensor_name:  row.sensor_name || null,
      city:         row.city || null,
      latitude:     row.latitude  != null ? Number(row.latitude)  : null,
      longitude:    row.longitude != null ? Number(row.longitude) : null,
      pollutant:    pollutant,
      value:        v,
      unit:         unit,
      datetime_utc: dt.toISOString(),
      source:       row.source || 'OpenAQ',
      _new_last_line: row._new_last_line || null,
    }
  });
}

return cleaned;
